#!/usr/bin/env bash
set -euo pipefail
command -v node >/dev/null 2>&1 || { echo 'Node.js is required.' >&2; exit 1; }
node <<'AF_STEM_HUB_PATCH'
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const files={"src/app/about/page.tsx": "import Image from 'next/image';\nimport Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\n\nexport const metadata = { title: 'About | A-Factor STEM Studio' };\n\nconst portfolio = 'https://mrdof-portfolio.vercel.app/';\n\nexport default function AboutPage() {\n  return (\n    <>\n      <AppHeader />\n      <main className=\"mx-auto max-w-4xl space-y-5 px-4 py-5 text-gray-900 sm:px-6 sm:py-8\">\n        <section className=\"rounded-2xl border border-indigo-100 bg-indigo-50 p-4 sm:p-6\">\n          <p className=\"text-xs font-semibold uppercase tracking-wide text-indigo-700\">A-Factor STEM Studio</p>\n          <h1 className=\"mt-1 text-2xl font-bold tracking-tight sm:text-4xl\">Learn STEM by doing</h1>\n          <p className=\"mt-2 max-w-2xl text-sm leading-relaxed text-gray-700 sm:text-base\">\n            A-Factor brings interactive STEM learning to students and teachers, with African classrooms in mind.\n            Change a variable, observe what happens and connect the result to the science or mathematics behind it.\n          </p>\n          <div className=\"mt-4 flex flex-wrap gap-2\">\n            <Link href=\"/stem\" className=\"inline-flex min-h-11 items-center rounded-lg bg-indigo-700 px-4 text-sm font-semibold text-white hover:bg-indigo-800\">\n              Explore all simulations\n            </Link>\n            <Link href=\"/tutor\" className=\"inline-flex min-h-11 items-center rounded-lg border border-indigo-200 bg-white px-4 text-sm font-semibold text-indigo-800\">\n              Open STEM Tutor\n            </Link>\n          </div>\n        </section>\n\n        <section aria-labelledby=\"learning-at-afactor\">\n          <h2 id=\"learning-at-afactor\" className=\"text-lg font-semibold\">What you can do</h2>\n          <ul className=\"mt-2 grid gap-2 sm:grid-cols-2\">\n            <li className=\"rounded-xl border border-gray-200 bg-white p-3 text-sm leading-relaxed text-gray-700\">\n              <strong className=\"block text-gray-900\">Explore across subjects</strong>\n              Investigate atoms, cells, materials, Earth systems and mathematical relationships.\n              Use circuit and materials simulations to connect scientific ideas to technology and engineering.\n            </li>\n            <li className=\"rounded-xl border border-gray-200 bg-white p-3 text-sm leading-relaxed text-gray-700\">\n              <strong className=\"block text-gray-900\">Teach and practise</strong>\n              Run classroom demonstrations, compare predictions with results and use worked examples and exercises where available.\n            </li>\n          </ul>\n        </section>\n\n        <details className=\"rounded-xl border border-gray-200 bg-white p-3\">\n          <summary className=\"cursor-pointer text-sm font-semibold\">Curriculum and language support</summary>\n          <p className=\"mt-2 text-sm leading-relaxed text-gray-600\">\n            Explore activities tagged for WAEC, NECO, IGCSE, JUPEB and SAT on the subject pages.\n            The topic explorer offers English, Yorùbá, Hausa and Igbo options.\n          </p>\n        </details>\n\n        <section aria-labelledby=\"founder-heading\" className=\"flex items-start gap-3 rounded-xl border border-gray-200 bg-white p-3 sm:gap-4 sm:p-4\">\n          <Image src=\"/iamdof-avatar.jpg\" alt=\"Fatai Olalekan Dawodu\" width={64} height={64}\n            className=\"h-14 w-14 shrink-0 rounded-full object-cover sm:h-16 sm:w-16\" />\n          <div className=\"min-w-0\">\n            <h2 id=\"founder-heading\" className=\"text-base font-semibold\">IamDOF 🕶</h2>\n            <p className=\"text-sm text-gray-700\">Fatai Olalekan Dawodu · Founder and educator</p>\n            <p className=\"mt-1 text-sm leading-relaxed text-gray-600\">\n              I build A-Factor to make STEM easier to teach, explore and practise.\n            </p>\n            <a href={portfolio} className=\"mt-1 inline-flex min-h-10 items-center text-sm font-semibold text-indigo-700 hover:underline\">\n              View my portfolio →\n            </a>\n          </div>\n        </section>\n      </main>\n    </>\n  );\n}\n", "src/app/page.tsx": "'use client';\nimport { useState, useCallback, useRef } from 'react';\nimport Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { PromptBar } from '@/components/ai/PromptBar';\nimport { ProjectileCanvas } from '@/components/simulation/ProjectileCanvas';\nimport { SimulationStats } from '@/components/simulation/SimulationStats';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { ParamControls } from '@/components/simulation/ParamControls';\nimport type { AIPromptResponse } from '@/types/ai';\nimport type { ProjectileParams, ProjectileState } from '@/lib/physics/projectile';\nimport type { GraphDataPoint } from '@/types/simulation';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\nconst DEFAULT_PARAMS: ProjectileParams = { initialVelocity: 20, angle: 45, gravity: 9.81, mass: 1 };\n\nexport default function HomePage() {\n  const [params, setParams] = useState<ProjectileParams>(DEFAULT_PARAMS);\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [liveState, setLiveState] = useState<ProjectileState | null>(null);\n  const [isComplete, setIsComplete] = useState(false);\n  const [lastResponse, setLastResponse] = useState<AIPromptResponse | null>(null);\n  const [resetKey, setResetKey] = useState(0);\n\n  const handleAIResult = useCallback((response: AIPromptResponse) => {\n    setLastResponse(response);\n    if (response.simulationType === 'projectile_motion') {\n      const p = response.params as ProjectileParams;\n      setParams({\n        initialVelocity: Number(p.initialVelocity) || 20,\n        angle: Number(p.angle) || 45,\n        gravity: Number(p.gravity) || 9.81,\n        mass: Number(p.mass) || 1,\n      });\n    }\n    setIsRunning(false); setIsPaused(false);\n    setLiveState(null); setIsComplete(false);\n    setResetKey(k => k + 1);\n  }, []);\n\n  const handleRun = () => { setIsRunning(true); setIsPaused(false); setIsComplete(false); };\n  const handlePause = () => setIsPaused(p => !p);\n  const handleReset = () => {\n    setIsRunning(false); setIsPaused(false);\n    setLiveState(null); setIsComplete(false);\n    setResetKey(k => k + 1);\n  };\n  const handleParamChange = (next: ProjectileParams) => {\n    setParams(next); setIsRunning(false); setIsPaused(false);\n    setLiveState(null); setIsComplete(false);\n    setResetKey(k => k + 1);\n  };\n  const handleTick = useCallback((s: ProjectileState) => setLiveState(s), []);\n  const handleComplete = useCallback((_: GraphDataPoint[]) => { setIsComplete(true); }, []);\n  const currentSpeed = liveState ? Math.sqrt(liveState.vx ** 2 + liveState.vy ** 2) : undefined;\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 720, 320, 900);\n\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n\n        {/* Hero prompt section */}\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-6 sm:py-8\">\n            <div className=\"mb-1 flex items-center gap-2\">\n              <span className=\"rounded-full bg-indigo-50 px-3 py-0.5 text-xs font-medium text-indigo-600\">\n                Phase 1 · Projectile motion\n              </span>\n              <Link href=\"/stem\" className=\"text-xs text-gray-400 hover:text-indigo-600 transition\">\n                All simulations →\n              </Link>\n              <Link href=\"/mathematics\" className=\"text-xs text-gray-400 hover:text-indigo-600 transition\">\n                Mathematics →\n              </Link>\n            </div>\n            <h2 className=\"text-base sm:text-lg font-semibold text-gray-900 mb-1\">\n              Describe your simulation\n            </h2>\n            <p className=\"text-xs text-gray-400 mb-4\">\n              Choose from all registered topics. Prepare supported settings and read explanations in English, Yoruba, Hausa or Igbo without a paid AI API.\n            </p>\n            <PromptBar onResult={handleAIResult} />\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-6 space-y-4\">\n\n          {/* AI explanation */}\n          {lastResponse && (\n            <div className=\"rounded-2xl border border-indigo-100 bg-indigo-50 px-4 sm:px-6 py-4\">\n              <p className=\"text-xs font-medium text-indigo-400 mb-1 uppercase tracking-wide\">\n                {lastResponse.title}\n              </p>\n              <p className=\"text-xs sm:text-sm text-indigo-800 leading-relaxed\">\n                {lastResponse.explanation}\n              </p>\n              {lastResponse.suggestedFollowUps?.length > 0 && (\n                <div className=\"mt-3 flex flex-wrap gap-2\">\n                  {lastResponse.suggestedFollowUps.map(q => (\n                    <span key={q} className=\"rounded-full border border-indigo-200 bg-white px-2.5 py-1 text-xs text-indigo-600\">\n                      {q}\n                    </span>\n                  ))}\n                </div>\n              )}\n            </div>\n          )}\n\n          {/* Main simulation area — stack on mobile, side by side on desktop */}\n          <div className=\"flex flex-col lg:grid lg:grid-cols-[1fr_260px] gap-4\">\n\n            {/* Canvas + controls */}\n            <div className=\"space-y-3 min-w-0\">\n              <div ref={canvasBoxRef}>\n                <ProjectileCanvas\n                  key={resetKey}\n                  params={params}\n                  isRunning={isRunning}\n                  isPaused={isPaused}\n                  onTick={handleTick}\n                  onComplete={handleComplete}\n                  width={canvasSize.width}\n                  height={canvasSize.height}\n                />\n              </div>\n              <div className=\"flex flex-wrap items-center gap-3 justify-between\">\n                <SimulationControls\n                  isRunning={isRunning && !isComplete}\n                  isPaused={isPaused}\n                  onRun={handleRun}\n                  onPause={handlePause}\n                  onReset={handleReset}\n                />\n                {isComplete && (\n                  <span className=\"text-xs font-medium text-emerald-600\">\n                    ✓ Complete — press Reset to go again\n                  </span>\n                )}\n              </div>\n              <SimulationStats\n                params={params}\n                elapsedTime={liveState?.time}\n                currentHeight={liveState ? Math.max(0, liveState.y) : undefined}\n                currentSpeed={currentSpeed}\n              />\n            </div>\n\n            {/* Param controls — below canvas on mobile */}\n            <div>\n              <ParamControls\n                params={params}\n                onChange={handleParamChange}\n                disabled={isRunning && !isComplete}\n              />\n            </div>\n          </div>\n\n          {/* Link to all simulations */}\n          <div className=\"rounded-2xl border border-gray-200 bg-white p-4 sm:p-5 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3\">\n            <div>\n              <p className=\"text-sm font-medium text-gray-900 mb-0.5\">More simulations</p>\n              <p className=\"text-xs text-gray-400\">Explore physics, chemistry, biology, mathematics and geophysics.</p>\n            </div>\n            <Link href=\"/stem\"\n              className=\"shrink-0 rounded-xl bg-indigo-600 px-5 py-2.5 text-sm font-medium text-white hover:bg-indigo-700 transition\">\n              Browse all →\n            </Link>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/components/layout/SimulationsMenu.tsx": "'use client';\nimport { useState, useRef, useEffect, useId } from 'react';\nimport Link from 'next/link';\nimport { usePathname } from 'next/navigation';\nimport { SUBJECTS, isSubjectPath, type Subject } from '@/lib/subjects';\n\nfunction Chevron({ open }: { open: boolean }) {\n  return (\n    <svg\n      width=\"10\" height=\"10\" viewBox=\"0 0 10 10\" fill=\"none\" stroke=\"currentColor\"\n      strokeWidth=\"1.6\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\"\n      className={`transition-transform ${open ? 'rotate-180' : ''}`}\n    >\n      <path d=\"M2 3.5l3 3 3-3\" />\n    </svg>\n  );\n}\n\nfunction SoonTag() {\n  return (\n    <span className=\"rounded-full bg-gray-100 px-1.5 py-0.5 text-[10px] font-medium text-gray-400\">\n      Coming soon\n    </span>\n  );\n}\n\n// One row in the dropdown. 'soon' subjects are greyed out and not clickable.\nfunction SubjectRow({ subject, current, onNavigate }: { subject: Subject; current: boolean; onNavigate: () => void }) {\n  const body = (\n    <>\n      <span className=\"mt-0.5 text-lg leading-none\" aria-hidden=\"true\">{subject.icon}</span>\n      <span className=\"min-w-0\">\n        <span className={`flex items-center gap-2 text-sm font-medium ${current ? 'text-indigo-700' : 'text-gray-800'}`}>\n          {subject.label}\n          {subject.status === 'soon' && <SoonTag />}\n        </span>\n        <span className=\"block text-xs leading-snug text-gray-500\">{subject.description}</span>\n      </span>\n    </>\n  );\n\n  if (subject.status !== 'live') {\n    return <div className=\"flex cursor-not-allowed items-start gap-3 rounded-lg px-3 py-2 opacity-60\">{body}</div>;\n  }\n  return (\n    <Link\n      href={subject.href}\n      onClick={onNavigate}\n      aria-current={current ? 'page' : undefined}\n      className={`flex items-start gap-3 rounded-lg px-3 py-2 transition ${current ? 'bg-indigo-50' : 'hover:bg-gray-50'}`}\n    >\n      {body}\n    </Link>\n  );\n}\n\n/** Desktop: a \"Simulations ▾\" button that reveals the subject list. */\nexport function SimulationsMenu() {\n  const pathname = usePathname();\n  const [open, setOpen] = useState(false);\n  const wrapRef = useRef<HTMLDivElement>(null);\n  const panelId = useId();\n  const active = pathname === '/stem' || SUBJECTS.some(s => s.status === 'live' && isSubjectPath(pathname, s));\n\n  // Close on outside click or Escape while open.\n  useEffect(() => {\n    if (!open) return;\n    const onDown = (e: MouseEvent) => {\n      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setOpen(false);\n    };\n    const onKey = (e: KeyboardEvent) => {\n      if (e.key === 'Escape') setOpen(false);\n    };\n    document.addEventListener('mousedown', onDown);\n    document.addEventListener('keydown', onKey);\n    return () => {\n      document.removeEventListener('mousedown', onDown);\n      document.removeEventListener('keydown', onKey);\n    };\n  }, [open]);\n\n  return (\n    <div ref={wrapRef} className=\"relative\">\n      <button\n        type=\"button\"\n        onClick={() => setOpen(v => !v)}\n        aria-expanded={open}\n        aria-controls={panelId}\n        className={`flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-sm transition ${\n          active || open\n            ? 'bg-indigo-50 text-indigo-700 font-medium'\n            : 'text-gray-500 hover:text-gray-900 hover:bg-gray-50'\n        }`}\n      >\n        Simulations\n        <Chevron open={open} />\n      </button>\n\n      {/* Always rendered (just hidden when closed) so the links exist in the page HTML. */}\n      <div\n        id={panelId}\n        className={`${open ? 'block' : 'hidden'} absolute left-0 top-full z-50 mt-2 w-72 rounded-xl border border-gray-200 bg-white p-1.5 shadow-lg`}\n      >\n        <p className=\"px-3 pb-1 pt-1.5 text-[10px] font-medium uppercase tracking-wide text-gray-400\">\n          Choose a subject\n        </p>\n        <Link href=\"/stem\" aria-current={pathname === '/stem' ? 'page' : undefined}\n            onClick={() => setOpen(false)} className=\"block rounded-lg px-3 py-2 text-sm font-semibold text-indigo-700 hover:bg-indigo-50\">\n            All STEM simulations\n          </Link>\n          {SUBJECTS.map(s => (\n          <SubjectRow\n            key={s.slug}\n            subject={s}\n            current={s.status === 'live' && isSubjectPath(pathname, s)}\n            onNavigate={() => setOpen(false)}\n          />\n        ))}\n      </div>\n    </div>\n  );\n}\n\n/** Mobile: an expandable \"Simulations\" section with the subjects indented beneath it. */\nexport function SimulationsMobileMenu({ onNavigate }: { onNavigate?: () => void }) {\n  const pathname = usePathname();\n  const [open, setOpen] = useState(true); // the mobile menu is already opened on purpose, so show the subjects\n  const panelId = useId();\n  const active = pathname === '/stem' || SUBJECTS.some(s => s.status === 'live' && isSubjectPath(pathname, s));\n\n  return (\n    <div>\n      <button\n        type=\"button\"\n        onClick={() => setOpen(v => !v)}\n        aria-expanded={open}\n        aria-controls={panelId}\n        className={`flex w-full items-center justify-between rounded-lg px-3 py-2 text-sm transition ${\n          active ? 'bg-indigo-50 text-indigo-700 font-medium' : 'text-gray-600 hover:bg-gray-50'\n        }`}\n      >\n        Simulations\n        <Chevron open={open} />\n      </button>\n      {open && (\n        <div id={panelId} className=\"ml-3 mt-1 space-y-0.5 border-l border-gray-100 pl-2\">\n          <Link href=\"/stem\" aria-current={pathname === '/stem' ? 'page' : undefined}\n            onClick={() => onNavigate?.()} className=\"block rounded-lg px-3 py-2 text-sm font-semibold text-indigo-700 hover:bg-indigo-50\">\n            All STEM simulations\n          </Link>\n          {SUBJECTS.map(s => (\n            <SubjectRow\n              key={s.slug}\n              subject={s}\n              current={s.status === 'live' && isSubjectPath(pathname, s)}\n              onNavigate={() => onNavigate?.()}\n            />\n          ))}\n        </div>\n      )}\n    </div>\n  );\n}\n", "src/components/layout/AppHeader.tsx": "'use client';\nimport { SubjectNavigation } from '@/components/layout/SubjectNavigation';\nimport { TopicContext } from '@/components/explorer/TopicContext';\n\nimport { useState, useEffect, useId } from 'react';\nimport Link from 'next/link';\nimport Image from 'next/image';\nimport { usePathname } from 'next/navigation';\nimport { SimulationsMenu, SimulationsMobileMenu } from '@/components/layout/SimulationsMenu';\n\nconst NAV = [\n  \n  { label: 'STEM Tutor', href: '/tutor' },\n  // { label: 'Geophysics', href: '/geophysics' },\n  { label: 'About', href: '/about' },\n];\n\nexport function AppHeader() {\n  const [open, setOpen] = useState(false);\n  const pathname = usePathname();\n  const menuId = useId();\n  useEffect(() => { setOpen(false); }, [pathname]);\n\n  return (\n    <><header className=\"sticky top-0 z-40 border-b border-gray-200 bg-white/95 backdrop-blur-sm\">\n      <div className=\"mx-auto max-w-7xl px-4 sm:px-6\">\n        <div className=\"flex h-14 items-center justify-between\">\n          {/* Logo */}\n          <Link href=\"/\" className=\"flex shrink-0 items-center gap-2 group\">\n            <Image src=\"/icon.png\" alt=\"A-Factor STEM Studio\" width={32} height={32}\n              className=\"h-7 w-7 rounded-lg\" priority />\n            <div className=\"leading-none\">\n              <span className=\"text-sm font-semibold text-gray-900\">A-Factor</span>\n              <span className=\"hidden sm:block text-[10px] text-gray-400 leading-none\">STEM Studio</span>\n            </div>\n          </Link>\n\n          {/* Desktop nav */}\n          <nav className=\"hidden lg:flex items-center gap-1\">\n            <SimulationsMenu />\n            {NAV.map(n => (\n              <Link key={n.href} href={n.href}\n                className={`px-3 py-1.5 rounded-lg text-sm transition ${\n                  pathname.startsWith(n.href)\n                    ? 'bg-indigo-50 text-indigo-700 font-medium'\n                    : 'text-gray-500 hover:text-gray-900 hover:bg-gray-50'\n                }`}>\n                {n.label}\n              </Link>\n            ))}\n            <Link href=\"/minitab\"\n              className={`px-3 py-1.5 rounded-lg text-sm transition ${\n                pathname.startsWith('/minitab')\n                  ? 'bg-indigo-50 text-indigo-700 font-medium'\n                  : 'text-gray-500 hover:text-gray-900 hover:bg-gray-50'\n              }`}>\n              Student Login\n            </Link>\n            <Link href=\"/explore\"\n              className=\"ml-2 rounded-lg bg-indigo-600 px-4 py-1.5 text-sm font-medium text-white hover:bg-indigo-700 transition\">\n              Try now\n            </Link>\n          </nav>\n\n          {/* Mobile menu button */}\n          <button onClick={() => setOpen(v => !v)}\n            className=\"lg:hidden flex min-h-11 min-w-11 items-center justify-center rounded-lg p-2 text-gray-500 hover:bg-gray-100 transition\"\n            aria-label=\"Menu\" aria-expanded={open} aria-controls={menuId}>\n            <svg width=\"18\" height=\"18\" viewBox=\"0 0 18 18\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.5\" strokeLinecap=\"round\">\n              {open\n                ? <><path d=\"M3 3l12 12M15 3L3 15\"/></>\n                : <><path d=\"M2 5h14M2 9h14M2 13h14\"/></>\n              }\n            </svg>\n          </button>\n        </div>\n\n        {/* Mobile nav */}\n        {open && (\n          <div id={menuId} className=\"lg:hidden max-h-[calc(100dvh-3.5rem)] overflow-y-auto overscroll-contain border-t border-gray-100 py-3 space-y-1\">\n            <SimulationsMobileMenu onNavigate={() => setOpen(false)} />\n            {NAV.map(n => (\n              <Link key={n.href} href={n.href} onClick={() => setOpen(false)}\n                className={`block px-3 py-3 rounded-lg text-sm transition ${\n                  pathname.startsWith(n.href)\n                    ? 'bg-indigo-50 text-indigo-700 font-medium'\n                    : 'text-gray-600 hover:bg-gray-50'\n                }`}>\n                {n.label}\n              </Link>\n            ))}\n            <Link href=\"/minitab\" onClick={() => setOpen(false)}\n              className={`block px-3 py-3 rounded-lg text-sm transition ${\n                pathname.startsWith('/minitab')\n                  ? 'bg-indigo-50 text-indigo-700 font-medium'\n                  : 'text-gray-600 hover:bg-gray-50'\n              }`}>\n              Student Login\n            </Link>\n            <Link href=\"/explore\" onClick={() => setOpen(false)}\n              className=\"block mt-2 rounded-lg bg-indigo-600 px-3 py-2 text-sm font-medium text-white text-center\">\n              Try now\n            </Link>\n          </div>\n        )}\n      </div>\n    </header><SubjectNavigation pathname={pathname} /><TopicContext /></>\n  );\n}\n", "src/app/stem/page.tsx": "import Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { topics } from '@/lib/explorer/catalog';\nimport { SUBJECTS } from '@/lib/subjects';\n\nexport const metadata = { title: 'Explore STEM simulations | A-Factor STEM Studio' };\n\nconst groups = [\n  ...SUBJECTS.filter(subject => subject.status === 'live'),\n  { slug: 'geophysics', label: 'Geophysics', href: '/geophysics', icon: '🌍', description: 'Earth, space and field methods' },\n].map(subject => ({\n  ...subject,\n  simulations: topics.filter(topic => !topic.protected && topic.subject === subject.label),\n})).filter(group => group.simulations.length > 0);\n\nexport default function StemCatalog() {\n  return (\n    <>\n      <AppHeader />\n      <main className=\"mx-auto max-w-7xl px-4 py-5 text-gray-900 sm:px-6 sm:py-8\">\n        <h1 className=\"text-2xl font-bold tracking-tight sm:text-4xl\">Explore STEM simulations</h1>\n        <p className=\"mt-2 max-w-2xl text-sm leading-relaxed text-gray-600\">\n          Choose a subject, then open a simulation to test an idea, change a variable or work through a classroom activity.\n        </p>\n        <nav aria-label=\"Jump to a subject\" className=\"mt-4 flex flex-wrap gap-2\">\n          {groups.map(group => (\n            <a key={group.slug} href={`#${group.slug}`}\n              className=\"inline-flex min-h-10 items-center rounded-lg border border-indigo-100 bg-indigo-50 px-3 text-sm font-medium text-indigo-800\">\n              <span aria-hidden=\"true\" className=\"mr-2\">{group.icon}</span>{group.label}\n            </a>\n          ))}\n        </nav>\n\n        <div className=\"mt-5 space-y-5\">\n          {groups.map(group => (\n            <section key={group.slug} id={group.slug} className=\"scroll-mt-20 rounded-xl border border-gray-200 bg-white p-3 sm:p-4\">\n              <div className=\"flex flex-wrap items-center justify-between gap-2\">\n                <h2 className=\"text-lg font-semibold\">{group.label}</h2>\n                <Link href={group.href} className=\"text-sm font-medium text-indigo-700 hover:underline\">\n                  {group.label} hub →\n                </Link>\n              </div>\n              <p className=\"mt-1 text-sm text-gray-600\">{group.description}</p>\n              <ul className=\"mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3\">\n                {group.simulations.map(simulation => (\n                  <li key={simulation.id}>\n                    <Link href={simulation.route} className=\"flex min-h-11 items-center rounded-lg bg-gray-50 px-3 py-2 text-sm font-medium text-gray-800 hover:bg-indigo-50 hover:text-indigo-800\">\n                      {simulation.title}\n                    </Link>\n                  </li>\n                ))}\n              </ul>\n            </section>\n          ))}\n        </div>\n        <p className=\"mt-5 text-sm text-gray-600\">\n          Open the <Link href=\"/minitab\" className=\"font-semibold text-indigo-700 hover:underline\">student classroom</Link> for simulations that require sign-in.\n        </p>\n      </main>\n    </>\n  );\n}\n", "src/components/layout/SubjectNavigation.tsx": "import Link from 'next/link';\nimport { SUBJECTS, isSubjectPath } from '@/lib/subjects';\n\nexport function SubjectNavigation({ pathname }: { pathname: string }) {\n  const subjects = SUBJECTS.filter(subject => subject.status === 'live');\n  const current = subjects.find(subject => isSubjectPath(pathname, subject));\n\n  if (!current && pathname !== '/stem') return null;\n\n  const links = [{ href: '/stem', label: 'All STEM' }, ...subjects];\n  return (\n    <nav aria-label=\"Simulation subjects\" className=\"border-b border-gray-200 bg-white\">\n      <div className=\"mx-auto flex max-w-7xl gap-1 overflow-x-auto px-3 py-1 sm:px-6\">\n        {links.map(link => {\n          const selected = link.href === (current?.href ?? pathname);\n          return (\n            <Link key={link.href} href={link.href} aria-current={selected ? 'location' : undefined}\n              className={`inline-flex min-h-10 shrink-0 items-center rounded-lg px-3 text-sm font-medium ${selected ? 'bg-indigo-50 text-indigo-800' : 'text-gray-600 hover:bg-gray-100'}`}>\n              {link.label}\n            </Link>\n          );\n        })}\n      </div>\n    </nav>\n  );\n}\n", "src/app/simulations/bjt-transistor/page.tsx": "// src/app/simulations/bjt-transistor/page.tsx\n'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { TopicContext } from '@/components/explorer/TopicContext';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\n\nimport React, { useState, useCallback } from 'react';\nimport Link from 'next/link';\nimport BjtCanvas from '@/components/simulation/BjtCanvas';\nimport { BjtParams, getPreset, PRESET_NAMES, PRESET_LABELS, REGION_DESCRIPTIONS, TOPOLOGY_DESCRIPTIONS } from '@/lib/physics/bjtTransistor';\n\nexport default function BjtTransistorPage() {\n  const [params, setParams] = useState<BjtParams>(getPreset('ce-active'));\n  const [activePreset, setActivePreset] = useState('ce-active');\n\n  const applyPreset = useCallback((name: string) => {\n    setParams(getPreset(name));\n    setActivePreset(name);\n  }, []);\n\n  const updateParam = useCallback(<K extends keyof BjtParams>(key: K, value: BjtParams[K]) => {\n    setParams(prev => ({ ...prev, [key]: value }));\n    setActivePreset('custom');\n  }, []);\n\n  const region = params.Vbe < (params.material === 'Si' ? 0.5 : 0.2) ? 'cutoff' : params.Vbe - params.Vce < 0.3 ? 'active' : 'saturation';\n\n  useTopicPreset(\"simulations-bjt-transistor\", { \"params.Vcc\": (value: number) => setParams(current => ({ ...current, Vcc: value })),\n    \"params.Vbe\": (value: number) => setParams(current => ({ ...current, Vbe: value })),\n    \"params.Vce\": (value: number) => setParams(current => ({ ...current, Vce: value })),\n    \"params.Rb\": (value: number) => setParams(current => ({ ...current, Rb: value })),\n    \"params.Rc\": (value: number) => setParams(current => ({ ...current, Rc: value })),\n    \"params.Re\": (value: number) => setParams(current => ({ ...current, Re: value })),\n    \"params.Rload\": (value: number) => setParams(current => ({ ...current, Rload: value })),\n    \"params.beta\": (value: number) => setParams(current => ({ ...current, beta: value })),\n    \"params.temperature\": (value: number) => setParams(current => ({ ...current, temperature: value })) }, {  });\n  return (\n    <div className=\"af-device min-h-screen bg-slate-950 text-slate-100 flex flex-col\">\n      <header className=\"border-b border-slate-800 bg-slate-950/80 backdrop-blur-md sticky top-0 z-50\">\n        <div className=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between\">\n          <div className=\"flex items-center gap-4\">\n            <Link href=\"/simulations\" className=\"text-slate-400 hover:text-slate-200 transition-colors text-sm font-medium\">← Simulations</Link>\n            <span className=\"text-slate-600\">|</span>\n            <h1 className=\"text-lg font-semibold text-slate-100\">BJT Transistor — Circuit Analysis</h1>\n          </div>\n          <div className=\"flex items-center gap-3\">\n            <span className=\"text-xs px-2 py-1 rounded-full bg-blue-500/10 text-blue-400 border border-blue-500/20\">Semiconductor Devices</span>\n            <span className=\"text-xs px-2 py-1 rounded-full bg-emerald-500/10 text-emerald-400 border border-emerald-500/20\">Live</span>\n          </div>\n        </div>\n      </header>\n      <TopicContext />\n\n      <main className=\"flex-1 p-6\">\n        <div className=\"max-w-6xl mx-auto\">\n          <p className=\"text-slate-400 mb-6\">\n            Explore BJT operating regions with real circuit topologies. Analyze Common-Emitter, Common-Collector, \n            and Common-Base amplifiers with load lines, gain calculations, and animated current flow.\n          </p>\n\n          <SimulationStage className=\"af-stage-dark grid grid-cols-1 lg:grid-cols-3 gap-6\">\n            <div data-stage-role=\"canvas\" className=\"lg:col-span-2\">\n              <BjtCanvas params={params} width={900} height={640} />\n            </div>\n\n            <div data-stage-role=\"parameters\" className=\"space-y-4\">\n              <div className=\"bg-slate-900 rounded-lg p-4 border border-slate-700\">\n                <h3 className=\"font-semibold mb-3 text-sm uppercase tracking-wide text-slate-400\">Circuit Topology</h3>\n                <div className=\"grid grid-cols-3 gap-2\">\n                  {(['common-emitter', 'common-collector', 'common-base'] as const).map(top => (\n                    <button\n                      key={top}\n                      onClick={() => updateParam('topology', top)}\n                      className={`px-2 py-2 rounded text-xs font-medium transition-colors ${\n                        params.topology === top ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'\n                      }`}\n                    >\n                      {top === 'common-emitter' ? 'CE' : top === 'common-collector' ? 'CC' : 'CB'}\n                    </button>\n                  ))}\n                </div>\n                <p className=\"text-xs text-slate-500 mt-2\">{TOPOLOGY_DESCRIPTIONS[params.topology]}</p>\n              </div>\n\n              <div className=\"bg-slate-900 rounded-lg p-4 border border-slate-700\">\n                <h3 className=\"font-semibold mb-3 text-sm uppercase tracking-wide text-slate-400\">Presets</h3>\n                <div className=\"grid grid-cols-2 gap-2\">\n                  {PRESET_NAMES.map(name => (\n                    <button\n                      key={name}\n                      onClick={() => applyPreset(name)}\n                      className={`px-3 py-2 rounded text-sm font-medium transition-colors ${\n                        activePreset === name ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'\n                      }`}\n                    >\n                      {PRESET_LABELS[name]}\n                    </button>\n                  ))}\n                </div>\n              </div>\n\n              <div className=\"bg-slate-900 rounded-lg p-4 border border-slate-700 space-y-4\">\n                <h3 className=\"font-semibold text-sm uppercase tracking-wide text-slate-400\">Parameters</h3>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Material</label>\n                  <select value={params.material} onChange={e => updateParam('material', e.target.value as BjtParams['material'])}\n                    className=\"w-full bg-slate-800 border border-slate-600 rounded px-3 py-2 text-sm\">\n                    <option value=\"Si\">Silicon (Vbe ≈ 0.7V)</option>\n                    <option value=\"Ge\">Germanium (Vbe ≈ 0.3V)</option>\n                  </select>\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Supply Voltage (Vcc): {params.Vcc} V</label>\n                  <input type=\"range\" min=\"3\" max=\"20\" step=\"0.5\" value={params.Vcc}\n                    onChange={e => updateParam('Vcc', parseFloat(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Base-Emitter Voltage (Vbe): {params.Vbe.toFixed(2)} V</label>\n                  <input type=\"range\" min=\"0\" max=\"1.0\" step=\"0.01\" value={params.Vbe}\n                    onChange={e => updateParam('Vbe', parseFloat(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Collector-Emitter Voltage (Vce): {params.Vce.toFixed(1)} V</label>\n                  <input type=\"range\" min=\"0\" max=\"15\" step=\"0.1\" value={params.Vce}\n                    onChange={e => updateParam('Vce', parseFloat(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Base Resistor (Rb): {params.Rb} kΩ</label>\n                  <input type=\"range\" min=\"10\" max=\"500\" step=\"10\" value={params.Rb}\n                    onChange={e => updateParam('Rb', parseInt(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Collector Resistor (Rc): {params.Rc} kΩ</label>\n                  <input type=\"range\" min=\"0.1\" max=\"10\" step=\"0.1\" value={params.Rc}\n                    onChange={e => updateParam('Rc', parseFloat(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Emitter Resistor (Re): {params.Re} kΩ</label>\n                  <input type=\"range\" min=\"0\" max=\"5\" step=\"0.1\" value={params.Re}\n                    onChange={e => updateParam('Re', parseFloat(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Load Resistor (Rload): {params.Rload} kΩ</label>\n                  <input type=\"range\" min=\"1\" max=\"50\" step=\"1\" value={params.Rload}\n                    onChange={e => updateParam('Rload', parseInt(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Current Gain (β): {params.beta}</label>\n                  <input type=\"range\" min=\"20\" max=\"500\" step=\"10\" value={params.beta}\n                    onChange={e => updateParam('beta', parseInt(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Temperature: {params.temperature} K</label>\n                  <input type=\"range\" min=\"200\" max=\"500\" step=\"10\" value={params.temperature}\n                    onChange={e => updateParam('temperature', parseInt(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n              </div>\n\n              <div className=\"bg-slate-900 rounded-lg p-4 border border-slate-700\">\n                <h3 className=\"font-semibold text-sm uppercase tracking-wide text-slate-400 mb-2\">Teacher Notes</h3>\n                <div className=\"text-sm text-slate-300 space-y-2\">\n                  <p className=\"text-green-400 font-medium\">Region: {region.toUpperCase()}</p>\n                  <p>{REGION_DESCRIPTIONS[region]}</p>\n                  <p className=\"text-blue-400 font-medium text-xs uppercase mt-2\">{params.topology.replace(/-/g, ' ').toUpperCase()} Topology</p>\n                  <p className=\"text-xs\">{TOPOLOGY_DESCRIPTIONS[params.topology]}</p>\n                  \n                  <div className=\"mt-3 p-2 bg-slate-800 rounded border border-slate-700\">\n                    <p className=\"text-yellow-400 font-medium text-xs uppercase mb-1\">Practice Problem</p>\n                    {params.topology === 'common-emitter' && (\n                      <>\n                        <p className=\"text-xs\">A CE amplifier has Vcc = 12V, Rc = 2kΩ, Re = 0.5kΩ, β = 100, Vbe = 0.7V. The Q-point is set at Vce = 6V.</p>\n                        <p className=\"text-xs text-slate-500 mt-1\">Find: (a) Ib, (b) Ic, (c) Rb needed, (d) Voltage gain with Rload = 10kΩ</p>\n                        <p className=\"text-xs text-slate-400 mt-1\">Answers: (a) 28.6μA, (b) 2.86mA, (c) 395kΩ, (d) Av ≈ -238</p>\n                      </>\n                    )}\n                    {params.topology === 'common-collector' && (\n                      <>\n                        <p className=\"text-xs\">An emitter follower has Vcc = 10V, Re = 2kΩ, β = 100, Vbe = 0.7V. Calculate the output voltage when Vin = 5V.</p>\n                        <p className=\"text-xs text-slate-500 mt-1\">Find: (a) Ve, (b) Ie, (c) Voltage gain, (d) Why is this called a \"buffer\"?</p>\n                        <p className=\"text-xs text-slate-400 mt-1\">Answers: (a) 4.3V, (b) 2.15mA, (c) Av ≈ 0.99, (d) High Zin, low Zout — isolates stages</p>\n                      </>\n                    )}\n                    {params.topology === 'common-base' && (\n                      <>\n                        <p className=\"text-xs\">A CB amplifier has Ie = 2mA, Rc = 3kΩ, α = 0.99. The input resistance is 12.5Ω.</p>\n                        <p className=\"text-xs text-slate-500 mt-1\">Find: (a) Ic, (b) Voltage gain, (c) Current gain, (d) Why is input Z so low?</p>\n                        <p className=\"text-xs text-slate-400 mt-1\">Answers: (a) 1.98mA, (b) Av ≈ 297, (c) Ai ≈ 0.99, (d) Input at emitter: re = VT/Ie ≈ 12.5Ω</p>\n                      </>\n                    )}\n                  </div>\n                  \n                  {params.beta > 200 && (\n                    <p className=\"text-xs\">High β means small base current controls large collector current — excellent for amplification but watch for thermal runaway.</p>\n                  )}\n                  {params.material === 'Ge' && (\n                    <p className=\"text-xs\">Germanium has lower Vbe (~0.3V) but higher leakage current (Ico doubles every 10°C vs every 6°C for Si).</p>\n                  )}\n                </div>\n              </div>\n            </div>\n          </SimulationStage>\n        </div>\n      </main>\n\n      <footer className=\"border-t border-slate-800 bg-slate-950 py-6\">\n        <div className=\"max-w-6xl mx-auto px-6 flex flex-col sm:flex-row items-center justify-between gap-4\">\n          <p className=\"text-sm text-slate-500\">BJT Transistor Simulation — Circuit Analysis Engine</p>\n          <div className=\"flex items-center gap-4 text-sm text-slate-500\">\n            <Link href=\"/stem\" className=\"hover:text-slate-300 transition-colors\">All STEM simulations</Link>\n            <Link href=\"/simulations/pn-junction\" className=\"hover:text-slate-300 transition-colors\">← PN Junction</Link>\n            <Link href=\"/simulations/mosfet\" className=\"hover:text-slate-300 transition-colors\">MOSFET →</Link>\n          </div>\n        </div>\n      </footer>\n    </div>\n  );\n}", "src/app/simulations/pn-junction/page.tsx": "// src/app/simulations/pn-junction/page.tsx\n'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { TopicContext } from '@/components/explorer/TopicContext';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\n\nimport React, { useState, useCallback } from 'react';\nimport Link from 'next/link';\nimport PnJunctionCanvas from '@/components/simulation/PnJunctionCanvas';\nimport { MaterialParams, getPreset, PRESET_NAMES, PRESET_LABELS } from '@/lib/physics/pnJunction';\n\nexport default function PnJunctionPage() {\n  const [params, setParams] = useState<MaterialParams>(getPreset('equilibrium'));\n  const [activePreset, setActivePreset] = useState('equilibrium');\n\n  const applyPreset = useCallback((name: string) => {\n    setParams(getPreset(name));\n    setActivePreset(name);\n  }, []);\n\n  const updateParam = useCallback(<K extends keyof MaterialParams>(key: K, value: MaterialParams[K]) => {\n    setParams(prev => ({ ...prev, [key]: value }));\n    setActivePreset('custom');\n  }, []);\n\n  const isRectifier = params.circuitMode !== 'diode';\n\n  useTopicPreset(\"simulations-pn-junction\", { \"params.appliedBias\": (value: number) => setParams(current => ({ ...current, appliedBias: value })),\n    \"params.Vin\": (value: number) => setParams(current => ({ ...current, Vin: value })),\n    \"params.Rload\": (value: number) => setParams(current => ({ ...current, Rload: value })),\n    \"params.freq\": (value: number) => setParams(current => ({ ...current, freq: value })),\n    \"params.temperature\": (value: number) => setParams(current => ({ ...current, temperature: value })) }, {  });\n  return (\n    <div className=\"af-device min-h-screen bg-slate-950 text-slate-100 flex flex-col\">\n      <header className=\"border-b border-slate-800 bg-slate-950/80 backdrop-blur-md sticky top-0 z-50\">\n        <div className=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between\">\n          <div className=\"flex items-center gap-4\">\n            <Link href=\"/simulations\" className=\"text-slate-400 hover:text-slate-200 transition-colors text-sm font-medium\">\n              ← Simulations\n            </Link>\n            <span className=\"text-slate-600\">|</span>\n            <h1 className=\"text-lg font-semibold text-slate-100\">PN Junction & Rectification</h1>\n          </div>\n          <div className=\"flex items-center gap-3\">\n            <span className=\"text-xs px-2 py-1 rounded-full bg-blue-500/10 text-blue-400 border border-blue-500/20\">Semiconductor Devices</span>\n            <span className=\"text-xs px-2 py-1 rounded-full bg-emerald-500/10 text-emerald-400 border border-emerald-500/20\">Live</span>\n          </div>\n        </div>\n      </header>\n      <TopicContext />\n\n      <main className=\"flex-1 p-6\">\n        <div className=\"max-w-6xl mx-auto\">\n          <p className=\"text-slate-400 mb-6\">\n            Explore depletion regions, built-in potential, and rectification. Switch between diode analysis \n            and real rectifier circuits with animated AC/DC conversion, current flow, and power calculations.\n          </p>\n\n          <SimulationStage className=\"af-stage-dark grid grid-cols-1 lg:grid-cols-3 gap-6\">\n            <div data-stage-role=\"canvas\" className=\"lg:col-span-2\">\n              <PnJunctionCanvas params={params} width={900} height={600} />\n            </div>\n\n            <div data-stage-role=\"parameters\" className=\"space-y-4\">\n              <div className=\"bg-slate-900 rounded-lg p-4 border border-slate-700\">\n                <h3 className=\"font-semibold mb-3 text-sm uppercase tracking-wide text-slate-400\">Circuit Mode</h3>\n                <div className=\"grid grid-cols-3 gap-2\">\n                  {(['diode', 'half-wave', 'full-wave'] as const).map(mode => (\n                    <button\n                      key={mode}\n                      onClick={() => updateParam('circuitMode', mode)}\n                      className={`px-2 py-2 rounded text-xs font-medium transition-colors ${\n                        params.circuitMode === mode\n                          ? 'bg-blue-600 text-white'\n                          : 'bg-slate-800 text-slate-300 hover:bg-slate-700'\n                      }`}\n                    >\n                      {mode === 'diode' ? 'Diode' : mode === 'half-wave' ? 'Half-Wave' : 'Full-Wave'}\n                    </button>\n                  ))}\n                </div>\n              </div>\n\n              <div className=\"bg-slate-900 rounded-lg p-4 border border-slate-700\">\n                <h3 className=\"font-semibold mb-3 text-sm uppercase tracking-wide text-slate-400\">Presets</h3>\n                <div className=\"grid grid-cols-2 gap-2\">\n                  {PRESET_NAMES.map(name => (\n                    <button\n                      key={name}\n                      onClick={() => applyPreset(name)}\n                      className={`px-3 py-2 rounded text-sm font-medium transition-colors ${\n                        activePreset === name ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'\n                      }`}\n                    >\n                      {PRESET_LABELS[name]}\n                    </button>\n                  ))}\n                </div>\n              </div>\n\n              <div className=\"bg-slate-900 rounded-lg p-4 border border-slate-700 space-y-4\">\n                <h3 className=\"font-semibold text-sm uppercase tracking-wide text-slate-400\">Parameters</h3>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Material</label>\n                  <select\n                    value={params.material}\n                    onChange={e => updateParam('material', e.target.value as MaterialParams['material'])}\n                    className=\"w-full bg-slate-800 border border-slate-600 rounded px-3 py-2 text-sm\"\n                  >\n                    <option value=\"Si\">Silicon (Si) — Vf ≈ 0.7V</option>\n                    <option value=\"Ge\">Germanium (Ge) — Vf ≈ 0.3V</option>\n                    <option value=\"GaAs\">GaAs — Vf ≈ 1.2V</option>\n                  </select>\n                </div>\n\n                {!isRectifier && (\n                  <>\n                    <div>\n                      <label className=\"block text-sm text-slate-400 mb-1\">\n                        P-side Doping (Na): {params.Na.toExponential(1)} cm⁻³\n                      </label>\n                      <input type=\"range\" min=\"14\" max=\"19\" step=\"0.5\"\n                        value={Math.log10(params.Na)}\n                        onChange={e => updateParam('Na', Math.pow(10, parseFloat(e.target.value)))}\n                        className=\"w-full accent-blue-500\" />\n                    </div>\n                    <div>\n                      <label className=\"block text-sm text-slate-400 mb-1\">\n                        N-side Doping (Nd): {params.Nd.toExponential(1)} cm⁻³\n                      </label>\n                      <input type=\"range\" min=\"14\" max=\"19\" step=\"0.5\"\n                        value={Math.log10(params.Nd)}\n                        onChange={e => updateParam('Nd', Math.pow(10, parseFloat(e.target.value)))}\n                        className=\"w-full accent-blue-500\" />\n                    </div>\n                    <div>\n                      <label className=\"block text-sm text-slate-400 mb-1\">\n                        Applied Bias: {params.appliedBias >= 0 ? '+' : ''}{params.appliedBias.toFixed(2)} V\n                      </label>\n                      <input type=\"range\" min=\"-10\" max=\"1\" step=\"0.05\"\n                        value={params.appliedBias}\n                        onChange={e => updateParam('appliedBias', parseFloat(e.target.value))}\n                        className=\"w-full accent-blue-500\" />\n                    </div>\n                  </>\n                )}\n\n                {isRectifier && (\n                  <>\n                    <div>\n                      <label className=\"block text-sm text-slate-400 mb-1\">\n                        AC Input (Vpeak): {params.Vin} V\n                      </label>\n                      <input type=\"range\" min=\"2\" max=\"20\" step=\"0.5\"\n                        value={params.Vin}\n                        onChange={e => updateParam('Vin', parseFloat(e.target.value))}\n                        className=\"w-full accent-blue-500\" />\n                    </div>\n                    <div>\n                      <label className=\"block text-sm text-slate-400 mb-1\">\n                        Load Resistance: {params.Rload} Ω\n                      </label>\n                      <input type=\"range\" min=\"100\" max=\"10000\" step=\"100\"\n                        value={params.Rload}\n                        onChange={e => updateParam('Rload', parseInt(e.target.value))}\n                        className=\"w-full accent-blue-500\" />\n                    </div>\n                    <div>\n                      <label className=\"block text-sm text-slate-400 mb-1\">\n                        Frequency: {params.freq} Hz\n                      </label>\n                      <input type=\"range\" min=\"10\" max=\"100\" step=\"5\"\n                        value={params.freq}\n                        onChange={e => updateParam('freq', parseInt(e.target.value))}\n                        className=\"w-full accent-blue-500\" />\n                    </div>\n                  </>\n                )}\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">\n                    Temperature: {params.temperature} K\n                  </label>\n                  <input type=\"range\" min=\"100\" max=\"600\" step=\"10\"\n                    value={params.temperature}\n                    onChange={e => updateParam('temperature', parseInt(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n              </div>\n\n              <div className=\"bg-slate-900 rounded-lg p-4 border border-slate-700\">\n                <h3 className=\"font-semibold text-sm uppercase tracking-wide text-slate-400 mb-2\">Teacher Notes</h3>\n                <div className=\"text-sm text-slate-300 space-y-2\">\n                  {!isRectifier && params.appliedBias === 0 && (\n                    <p><strong>Equilibrium:</strong> At zero bias, diffusion and drift currents balance. The depletion region forms as ionized donors/acceptors create a space charge. Built-in potential Vbi = (kT/q) ln(Na·Nd/ni²).</p>\n                  )}\n                  {!isRectifier && params.appliedBias > 0 && (\n                    <p><strong>Forward Bias:</strong> Reducing the barrier allows majority carriers to diffuse. Current follows Shockley: I = Is(e^(V/nVT) - 1). For Si, significant current flows above ~0.7V.</p>\n                  )}\n                  {!isRectifier && params.appliedBias < 0 && (\n                    <p><strong>Reverse Bias:</strong> Barrier increases, depletion widens. Only minority carriers contribute — tiny saturation current until avalanche breakdown at high reverse voltage.</p>\n                  )}\n                  {params.circuitMode === 'half-wave' && (\n                    <>\n                      <p><strong>Half-Wave Rectifier:</strong> Only positive half-cycles pass. One diode + load resistor. Vdc = (Vpeak - Vf)/π. Efficiency ≈ 40.6%. High ripple (121%).</p>\n                      <div className=\"mt-2 p-2 bg-slate-800 rounded border border-slate-700\">\n                        <p className=\"text-yellow-400 font-medium text-xs uppercase mb-1\">Practice Problem</p>\n                        <p className=\"text-xs\">A half-wave rectifier has Vpeak = 10V, Rload = 1kΩ, Si diode. Calculate: (a) DC output voltage, (b) DC load current, (c) PIV rating needed.</p>\n                        <p className=\"text-xs text-slate-500 mt-1\">Answers: (a) 2.96V, (b) 2.96mA, (c) 10V</p>\n                      </div>\n                    </>\n                  )}\n                  {params.circuitMode === 'full-wave' && (\n                    <>\n                      <p><strong>Full-Wave Bridge:</strong> 4 diodes conduct both half-cycles. Vdc = 2(Vpeak - Vf)/π. Efficiency ≈ 81.2%. Lower ripple (48%). No center-tapped transformer needed.</p>\n                      <div className=\"mt-2 p-2 bg-slate-800 rounded border border-slate-700\">\n                        <p className=\"text-yellow-400 font-medium text-xs uppercase mb-1\">Practice Problem</p>\n                        <p className=\"text-xs\">A bridge rectifier has Vpeak = 10V, Rload = 1kΩ, Si diodes. Calculate: (a) DC output voltage, (b) Total diode power loss, (c) Efficiency.</p>\n                        <p className=\"text-xs text-slate-500 mt-1\">Answers: (a) 5.91V, (b) 16.6mW, (c) ~81%</p>\n                      </div>\n                    </>\n                  )}\n                  {params.material !== 'Si' && (\n                    <p><strong>Material Effect:</strong> {params.material} has Vf ≈ {params.material === 'Ge' ? '0.3V' : '1.2V'}, affecting rectifier efficiency and output voltage.</p>\n                  )}\n                </div>\n              </div>\n            </div>\n          </SimulationStage>\n        </div>\n      </main>\n\n      <footer className=\"border-t border-slate-800 bg-slate-950 py-6\">\n        <div className=\"max-w-6xl mx-auto px-6 flex flex-col sm:flex-row items-center justify-between gap-4\">\n          <p className=\"text-sm text-slate-500\">PN Junction Simulation — Semiconductor Physics Engine</p>\n          <div className=\"flex items-center gap-4 text-sm text-slate-500\">\n            <Link href=\"/stem\" className=\"hover:text-slate-300 transition-colors\">All STEM simulations</Link>\n            <Link href=\"/simulations/band-theory\" className=\"hover:text-slate-300 transition-colors\">← Band Theory</Link>\n            <Link href=\"/simulations/bjt-transistor\" className=\"hover:text-slate-300 transition-colors\">BJT →</Link>\n          </div>\n        </div>\n      </footer>\n    </div>\n  );\n}"},expected={"src/app/about/page.tsx": "5d93b9397866ab03a376c31ac28a283e698fe12085cfe72506b50be347478de6", "src/app/page.tsx": "78cba041a52691b438c47a42081b7e94cb5b382b91009636b021eec4ca8b2291", "src/components/layout/SimulationsMenu.tsx": "c7f69c7475f3ebf4df6c919519582a5b9b0314c415441a49ae8d4cc75b9eafba", "src/components/layout/AppHeader.tsx": "80889480a0513115ed1666bdb45507ed980e475df88323f844c43b1dfdf62887", "src/app/stem/page.tsx": null, "src/components/layout/SubjectNavigation.tsx": null, "public/iamdof-avatar.jpg": null, "src/app/simulations/bjt-transistor/page.tsx": "7ee2a4c8bae2f2e78a93adf43e63e977aab50daf260cd23252cc5a3097f19095", "src/app/simulations/pn-junction/page.tsx": "a01848a107436b1437503951232457b930cf502a2122ddc27c0de6cdffcfba10"};
